import{_ as a,c as t,al as i,o as n}from"./chunks/framework.ByhWQ_D0.js";const h=JSON.parse('{"title":"Спеціальні повідомлення MAVLink","description":"","frontmatter":{},"headers":[],"relativePath":"uk/mavlink/custom_messages.md","filePath":"uk/mavlink/custom_messages.md"}'),o={name:"uk/mavlink/custom_messages.md"};function s(d,e,l,r,c,m){return n(),t("div",null,e[0]||(e[0]=[i('<h1 id="спеціальні-повідомлення-mavlink" tabindex="-1">Спеціальні повідомлення MAVLink <a class="header-anchor" href="#спеціальні-повідомлення-mavlink" aria-label="Permalink to &quot;Спеціальні повідомлення MAVLink&quot;">​</a></h1><p>A custom <a href="./../middleware/mavlink.html">MAVLink message</a> is one that isn&#39;t in the standard MAVLink definitions that are included into PX4 by default.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you use a custom definition you will fork and maintain PX4, your ground station, and any other SDKs that communicate with it. Загалом, щоб зменшити тягар обслуговування, слід використовувати (або доповнювати) стандартні визначення, якщо це можливо.</p></div><h2 id="adding-custom-xml" tabindex="-1">Adding Custom XML <a class="header-anchor" href="#adding-custom-xml" aria-label="Permalink to &quot;Adding Custom XML&quot;">​</a></h2><p>Custom definitions can be added in a new dialect file in the same directory as <a href="./../mavlink/adding_messages.html">when using the standard XML definitions</a>. For example, create <code>PX4-Autopilot/src/modules/mavlink/mavlink/message_definitions/v1.0/custom_messages.xml</code>, and set <code>CONFIG_MAVLINK_DIALECT</code> to build the new file for SITL. This dialect file should include <code>development.xml</code> so that all the standard definitions are also included.</p><p>For initial prototyping, or if you intend your message to be &quot;standard&quot;, you can also add your messages to <code>common.xml</code> (or <code>development.xml</code>). Це спрощує збірку, оскільки вам не потрібно модифікувати вже зібраний діалект.</p><p>The MAVLink developer guide explains how to define new messages in <a href="https://mavlink.io/en/guide/define_xml_element.html" target="_blank" rel="noreferrer">How to Define MAVLink Messages &amp; Enums</a>.</p><p>You can check that your new messages are built by inspecting the headers generated in the build directory (<code>/build/&lt;build target&gt;/mavlink/</code>). Якщо ваші повідомлення не збираються, вони можуть бути неправильно відформатовані або використовувати конфліктуючі ідентифікатори. Перевірте журнал збірки для отримання інформації.</p><p>Після того, як повідомлення створено, ви можете передавати, отримувати або використовувати його в інший спосіб, як описано в наступних розділах.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <a href="https://mavlink.io/en/getting_started/" target="_blank" rel="noreferrer">MAVLink Developer guide</a> has more information about using the MAVLink toolchain.</p></div><h2 id="альтернатива-створення-користувацьких-повідомлень-mavlink" tabindex="-1">Альтернатива створення користувацьких повідомлень MAVLink <a class="header-anchor" href="#альтернатива-створення-користувацьких-повідомлень-mavlink" aria-label="Permalink to &quot;Альтернатива створення користувацьких повідомлень MAVLink&quot;">​</a></h2><p>Іноді існує потреба в довільному повідомленні MAVLink з вмістом, який не повністю визначений.</p><p>Наприклад, при використанні MAVLink для інтерфейсу PX4 з вбудованим пристроєм, повідомлення, якими обмінюються автопілот і пристрій, можуть пройти кілька ітерацій, перш ніж вони будуть стабілізовані. У цьому випадку відновлення заголовків MAVLink може зайняти багато часу і призвести до помилок, а також переконатися, що обидва пристрої використовують одну і ту ж версію протоколу.</p><p>Альтернативним - і тимчасовим - рішенням є перепризначення налагоджувальних повідомлень. Instead of creating a custom MAVLink message <code>CA_TRAJECTORY</code>, you can send a message <code>DEBUG_VECT</code> with the string key <code>CA_TRAJ</code> and data in the <code>x</code>, <code>y</code> and <code>z</code> fields. See <a href="./../debug/debug_values.html">this tutorial</a> for an example usage of debug messages.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This solution is not efficient as it sends character string over the network and involves comparison of strings. Це повинно використовуватися лише для розробки!</p></div><h2 id="testing-updating-ground-stations" tabindex="-1">Testing &amp; Updating Ground Stations <a class="header-anchor" href="#testing-updating-ground-stations" aria-label="Permalink to &quot;Testing &amp; Updating Ground Stations&quot;">​</a></h2><p>Testing the code and updating ground stations is done in the same way as when <a href="./../mavlink/adding_messages.html">Adding New Standard MAVLink Definitions </a>.</p>',17)]))}const p=a(o,[["render",s]]);export{h as __pageData,p as default};
